using System.Runtime.InteropServices;
using System.Security.Cryptography;
using TerraRuntime.Contracts.Gameplay;
using TerraRuntime.Core;
using TerraRuntime.WorldGeneration.Vanilla;
using Xunit;

namespace TerraRuntime.Tests;

public sealed class DungeonPaintings1458Tests
{
    // Original TerrariaServer 1.4.5.8 SHA256 4B87890AC53D40F61DB5F928693A379ACF4CCBD8ED3B47EB32FB096F145DF034.
    // Full normalized tile arrays and shared RNG, not output generated by the candidate.
    public static IEnumerable<object[]> Cases => Reference.Split('\n', StringSplitOptions.RemoveEmptyEntries)
        .Select(line => line.Trim().Split('|')).Select(p => new object[]
        { int.Parse(p[0]), int.Parse(p[1]), int.Parse(p[2]), p[3], int.Parse(p[4]) });

    [Theory, MemberData(nameof(Cases))]
    public void Painting_search_objects_and_random_stream_match_original(int fixture, int palette, int seed, string expected, int next)
    {
        var tiles = DungeonSurfaceFeatureFixture1458.PaintingTiles(fixture, palette);
        var random = new RandomAdapter(seed);
        new DungeonPaintings1458(tiles, random, CancellationToken.None)
            .Place(DungeonSurfaceFeatureFixture1458.Bounds, (ushort)(7 + palette), 60,
                DungeonSurfaceFeatureFixture1458.Entrance(fixture));
        Assert.Equal(expected, Convert.ToHexString(SHA256.HashData(MemoryMarshal.AsBytes(tiles.Tiles))));
        Assert.Equal(next, random.Next());
    }

    [Fact]
    public void Cancellation_precedes_any_random_or_tile_mutation()
    {
        var tiles = DungeonSurfaceFeatureFixture1458.PaintingTiles(0, 0);
        var random = new RandomAdapter(42);
        Assert.Throws<OperationCanceledException>(() => new DungeonPaintings1458(tiles, random, new CancellationToken(true))
            .Place(DungeonSurfaceFeatureFixture1458.Bounds, 7, 60));
        Assert.Equal(new RandomAdapter(42).Next(), random.Next());
    }

    private sealed class RandomAdapter(int seed) : IWorldGenerationVanillaRandom
    {
        private readonly VanillaUnifiedRandom1458 random = new(seed);
        public int Next() => random.Next();
        public int Next(int max) => random.Next(max);
        public int Next(int min, int max) => random.Next(min, max);
        public double NextDouble() => random.NextDouble();
        public void NextBytes(byte[] bytes) => random.NextBytes(bytes);
    }

